mapper.select:
select gover.*, enter.country_id as countryId, enter.country_name as countryName, enter.province_id as provinceId, enter.province_name as provinceName, enter.city_id as cityId, enter.city_name as cityName, enter.region_id as regionId, enter.region_name as regionName, enter.business_name as businessName, enter.business_phone as businessPhone, enter.business_email as businessEmail, enter.credit_code as creditCode,
gover.create_time as informantDateTime,
gover.informant_date_time as informantDateTime,
project_warehousing.id as crmProjectInformationWarehousingId, project_warehousing.project_name as crmProjectInformationWarehousingName, basice_config1.name as unitPropertyAllocationConfigName, basice_config1.id as unitPropertyAllocationConfigId, basice_config2.name as unitClassConfigurationName, basice_config2.id as unitClassConfigurationId, basice_config3.name as industryConfigurationName, basice_config3.id as industryConfigurationId, basice_config4.name as unitReputationAllocationConfigName, basice_config4.id as unitReputationAllocationConfigId, user_a.name as informantUserName, user_b.name as createUserName from crm_government_warehousing as gover left join crm_enterprise_warehousing as enter on enter.id = gover.crm_enterprise_warehousing_id and enter.bool_delete_enum = 0 left join crm_basics_config as basice_config1 on basice_config1.id = enter.unit_property_allocation_config_id and basice_config1.bool_delete_enum = 0 left join crm_basics_config as basice_config2 on basice_config2.id = enter.unit_class_configuration_id and basice_config2.bool_delete_enum = 0 left join crm_basics_config as basice_config3 on basice_config3.id = enter.industry_configuration_id and basice_config3.bool_delete_enum = 0 left join crm_basics_config as basice_config4 on basice_config4.id = enter.unit_reputation_allocation_config_id and basice_config4.bool_delete_enum = 0 left join sys_user as user_a on user_a.id = gover.informant_user_id and user_a.bool_delete_enum = 0 left join sys_user as user_b on user_b.id = gover.create_user_id and user_b.bool_delete_enum = 0 left join crm_project_information_warehousing as project_warehousing on project_warehousing.id = gover.crm_project_information_warehousing_id and project_warehousing.bool_delete_enum = 0
gover.bool_delete_enum = 0
and gover.crm_record_type_enum = #{checkRecord}
and gover.crm_check_status_enum = #{crmCheckStatusEnum}
and DATE_FORMAT(gover.create_time, '%Y-%m-%d') >= #{startDate}
and DATE_FORMAT(gover.create_time, '%Y-%m-%d') <= #{endDate}
and DATE_FORMAT(gover.informant_date_time, '%Y-%m-%d') >= #{startDate}
and DATE_FORMAT(gover.informant_date_time, '%Y-%m-%d') <= #{endDate}
and enter.country_id = #{countryId}
and enter.province_id = #{provinceId}
and enter.city_id = #{cityId}
and enter.region_id = #{regionId}
and enter.unit_property_allocation_config_id = #{unitPropertyAllocationConfigId}
and enter.unit_class_configuration_id = #{unitClassConfigurationId}
and enter.industry_configuration_id = #{industryConfigurationId}
and enter.unit_reputation_allocation_config_id = #{unitReputationAllocationConfigId}
and enter.business_name like concat('%',#{businessName},'%')
and enter.credit_code like concat('%',#{creditCode},'%')
and user_a.name like concat('%',#{informantUserName},'%')
order by gover.create_time desc
order by gover.informant_date_time desc
